package com.example.Hospital.Management.System.controllers; import com.example.Hospital.Management.System.dtos.*; import com.example.Hospital.Management.System.services.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/patient") public class PatientController{private final PatientService s;public PatientController(PatientService s){this.s=s;}@PostMapping public ResponseEntity<PatientDTO> create(@Valid @RequestBody PatientDTO d){return ResponseEntity.status(201).body(s.create(d));}@GetMapping public List<PatientDTO> all(){return s.all();}@GetMapping("/{id}") public PatientDTO get(@PathVariable Long id){return s.get(id);}@PutMapping("/{id}") public PatientDTO update(@PathVariable Long id,@Valid @RequestBody PatientDTO d){return s.update(id,d);}@DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){s.delete(id);return ResponseEntity.noContent().build();}@GetMapping("/admitted/floor/{floor}") public List<PatientDTO> floor(@PathVariable Integer floor){return s.admittedOnFloor(floor);}@GetMapping("/outstanding-bills") public List<PatientDTO> outstanding(){return s.outstanding();}}
